@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&display=swap');
:root{--bg:#0e1822;--panel:#172430;--panel2:#1b2a37;--line:#293a47;--muted:#91a2ae;--text:#e9f0f3;--green:#a4ec71;--green2:#6bbf5a;--amber:#f2bd61;--blue:#70c5d5;--red:#ee8078;--font:'DM Sans',sans-serif;--mono:'DM Mono',monospace}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:var(--font);font-size:13px}.app-shell{max-width:1600px;margin:auto;min-height:100vh}.topbar{height:74px;padding:0 28px;border-bottom:1px solid #263541;display:flex;align-items:center;gap:40px;background:#111e29}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:var(--text);min-width:215px}.brand-mark{width:37px;height:37px;border:1px solid var(--green);border-radius:11px;color:var(--green);font-size:24px;font-weight:800;display:grid;place-items:center;transform:skew(-6deg)}.brand b{font-size:16px;letter-spacing:1.6px}.brand b span{color:var(--green)}.brand small,.airport-name small{display:block;color:#80919e;font-size:8px;letter-spacing:1.15px;margin-top:3px}.airport-name{display:flex;gap:10px;align-items:center;border-left:1px solid var(--line);padding-left:26px;margin-right:auto}.airport-name b{font-size:12px}.live-dot{display:inline-block;width:7px;height:7px;background:var(--green);border-radius:50%;box-shadow:0 0 9px #a4ec7180}.top-stats{display:flex;gap:25px}.top-stats>div{display:grid;gap:5px}.top-stats small{font-size:8px;letter-spacing:1px;color:#8596a1}.top-stats b{font-size:13px}.top-stats .clock{text-align:right;border-left:1px solid var(--line);padding-left:24px}.clock b{font:500 17px var(--mono)}.star{color:var(--amber)}.icon-btn{border:1px solid var(--line);color:#bac7cf;background:#1a2934;border-radius:8px;padding:8px 10px;cursor:pointer}.main-layout{display:grid;grid-template-columns:minmax(0,1fr) 344px;gap:18px;padding:18px 22px 24px}.game-column{min-width:0}.scene-wrap{height:455px;border:1px solid #30424d;border-radius:12px;overflow:hidden;position:relative;background:#657f71;box-shadow:0 10px 40px #0002}.scene-wrap canvas{width:100%;height:100%;display:block}.scene-topline{position:absolute;top:14px;left:16px;right:16px;display:flex;justify-content:space-between;align-items:center;pointer-events:none}.scene-label{background:#10202bd9;border:1px solid #ffffff20;border-radius:5px;padding:8px 11px;font:500 9px var(--mono);letter-spacing:.8px;display:flex;gap:8px;align-items:center}.scene-tools{display:flex;gap:5px;pointer-events:auto}.scene-tools button{border:1px solid #ffffff35;background:#13212cbd;color:#e6edef;border-radius:5px;width:30px;height:29px;font-size:17px;cursor:pointer}.scene-bottom{position:absolute;bottom:14px;left:16px;right:16px;display:flex;align-items:center;gap:13px}.camera-switch{border-radius:6px;display:flex;gap:2px;background:#111d27e8;border:1px solid #ffffff22;padding:3px}.camera-switch button{background:transparent;color:#9badb6;border:0;border-radius:4px;padding:8px 11px;font:500 9px var(--mono);cursor:pointer}.camera-switch button.active{background:#a4ec71;color:#18271f}.scene-hint{background:#13212de8;border:1px solid #ffffff22;border-radius:5px;color:#d4e0e3;padding:9px 12px;font-size:10px}.scene-hint span{color:var(--green);margin-left:8px}.weather-chip{margin-left:auto;background:#13212de8;border:1px solid #ffffff22;border-radius:5px;color:#d9e3e7;padding:9px 11px;font:10px var(--mono)}.panel{background:var(--panel);border:1px solid #263844;border-radius:10px;padding:17px}.bottom-grid{display:grid;grid-template-columns:1.55fr 1fr;gap:14px;margin-top:14px}.panel-heading{display:flex;align-items:center;justify-content:space-between}.eyebrow{font:500 8px var(--mono);letter-spacing:1.15px;color:#879aa6;display:block;margin-bottom:5px}.panel h2{margin:0;font-size:14px;font-weight:700;letter-spacing:.1px}.status-pill{font:500 8px var(--mono);vertical-align:2px;background:#283b39;color:var(--green);padding:4px 7px;border-radius:4px;margin-left:6px;letter-spacing:.3px}.text-btn{border:0;background:none;color:var(--green);font:500 8px var(--mono);letter-spacing:.5px;cursor:pointer}.flight-main{display:flex;align-items:center;margin-top:17px;gap:11px}.airline-badge{width:38px;height:38px;background:#eee;border-radius:7px;color:#c9313e;display:grid;place-items:center;font-size:13px;font-weight:800;font-style:italic}.flight-route{display:grid;gap:5px}.flight-route b{font-size:10px;letter-spacing:.6px}.flight-route b span{color:var(--green);padding:0 5px}.flight-route small{font-size:9px;color:#8da0aa}.turnaround{margin-left:auto;text-align:right;display:grid;gap:4px}.turnaround small{font:8px var(--mono);color:#84959f}.turnaround strong{font:500 15px var(--mono);color:var(--amber)}.progress-row{display:flex;align-items:center;gap:9px;margin-top:16px}.progress-track{height:4px;flex:1;background:#2c3b46;border-radius:4px;overflow:hidden}.progress-track i{height:100%;display:block;background:var(--green);border-radius:4px;transition:width .5s}.progress-row b{font:9px var(--mono);color:#a7b5bd}.task-strip{display:flex;gap:5px;margin-top:13px}.task-chip{flex:1;background:#202f3a;border-radius:4px;padding:6px 5px;color:#98aab4;font-size:8px;text-align:center;white-space:nowrap;overflow:hidden}.task-chip.done{color:#a6e980;background:#263a32}.task-chip.current{outline:1px solid #8bcf68;color:#e1f4d8}.objective-icon{color:var(--green);font-size:20px}.objective-panel p{font-size:10px;line-height:1.6;color:#9aabb5;margin:14px 0 18px}.objective-bottom{border-top:1px solid var(--line);padding-top:12px;display:flex;justify-content:space-between;align-items:end}.objective-bottom small{display:block;font:8px var(--mono);color:#8799a4;margin-bottom:5px}.objective-bottom b{font:500 14px var(--mono);color:var(--green)}.objective-bottom b span{font:9px var(--font);color:#9baab3}.mini-level{text-align:right}.mini-level span{font:8px var(--mono);color:#a4b3bb}.mini-level div{width:80px;height:4px;background:#2b3c47;border-radius:3px;margin-top:6px}.mini-level i{display:block;height:100%;background:#79b9dd;border-radius:3px}.sidebar{display:flex;flex-direction:column;gap:12px}.sidebar .panel{padding:15px}.flight-count{font:9px var(--mono);color:#82949f;margin-left:4px}.add-flight,.hire-btn{cursor:pointer;background:#293b46;color:var(--green);border:1px solid #344a53;border-radius:5px}.add-flight{width:28px;height:27px;font-size:19px}.flight-list{margin-top:11px}.flight-card{padding:10px 8px;display:flex;gap:9px;align-items:center;border-top:1px solid #263742;cursor:pointer;transition:background .15s;border-radius:4px}.flight-card:hover,.flight-card.selected{background:#21323d}.flight-card.selected{box-shadow:inset 2px 0 var(--green)}.flight-time{font:10px var(--mono);color:#c3d0d5;width:39px}.flight-mini-logo{width:27px;height:27px;border-radius:5px;background:#ececec;color:#bf3541;display:grid;place-items:center;font-size:9px;font-weight:800}.flight-card:nth-child(2) .flight-mini-logo{color:#273a85}.flight-card:nth-child(3) .flight-mini-logo{color:#a46b10}.flight-info{flex:1;min-width:0}.flight-info b{display:block;font-size:9px;letter-spacing:.2px}.flight-info small{color:#899ba5;font-size:8px;display:block;margin-top:3px}.flight-status{font:7px var(--mono);color:var(--amber);text-align:right}.flight-status.done{color:var(--green)}.wide-quiet{width:100%;border:0;border-top:1px solid #263742;padding:11px 3px 1px;background:none;color:#91a2ac;display:flex;justify-content:space-between;font:8px var(--mono);letter-spacing:.7px;cursor:pointer}.wide-quiet span{color:var(--green)}.hire-btn{font:8px var(--mono);padding:7px 8px}.crew-list{margin-top:10px}.crew-row{display:flex;align-items:center;gap:9px;padding:8px 0;border-top:1px solid #263742}.avatar{width:28px;height:28px;background:#344a4d;border-radius:6px;display:grid;place-items:center;font-size:15px}.crew-row:nth-child(2) .avatar{background:#494052}.crew-row:nth-child(3) .avatar{background:#53483a}.crew-data{flex:1}.crew-data b{display:block;font-size:9px}.crew-data small{display:block;color:#889ba5;font-size:8px;margin-top:3px}.crew-state{font:7px var(--mono);color:var(--green)}.crew-state.busy{color:var(--amber)}.crew-foot{border-top:1px solid #263742;margin-top:5px;padding-top:10px;display:flex;align-items:center;gap:8px}.crew-avatars{display:flex}.crew-avatars span{width:18px;height:18px;display:grid;place-items:center;background:#3c5151;border:1px solid var(--panel);border-radius:50%;font-size:9px;margin-right:-3px}.crew-foot small{color:#9aabb4;font-size:8px}.equipment-list{margin-top:8px}.equipment-row{display:flex;align-items:center;padding:8px 0;border-top:1px solid #263742;gap:9px}.equipment-icon{font-size:16px;color:#b0c1c6;width:24px;text-align:center}.equipment-row b{font-size:9px;display:block}.equipment-row small{color:#889ba5;font-size:8px;display:block;margin-top:3px}.equipment-count{font:10px var(--mono);margin-left:auto;color:#d3dfe2}.equipment-count.low{color:var(--amber)}.sidebar-footer{padding:11px 14px;background:#202f38;border:1px solid #35443e;border-left:3px solid var(--green);border-radius:7px;display:grid;gap:4px}.sidebar-footer span{font:8px var(--mono);color:var(--green);letter-spacing:.5px}.sidebar-footer b{font-size:9px}.sidebar-footer small{font-size:8px;color:#98a9b0}.work-controls{display:none;position:absolute;inset:auto 10px 58px 10px;align-items:end;justify-content:space-between;pointer-events:none}.work-controls button{pointer-events:auto;border:1px solid #ffffff44;background:#14232cd9;color:#fff;border-radius:8px;width:42px;height:42px;font-size:17px;touch-action:none}.work-controls>div{display:grid;grid-template-columns:repeat(3,42px);gap:4px}.work-controls>div button:first-child{grid-column:2}.work-controls .action-touch{width:auto;padding:0 14px;background:#a4ec71;color:#18241c;font:700 10px var(--mono)}.work-controls.visible{display:flex}.toast{position:absolute;top:60px;left:50%;transform:translate(-50%,-10px);background:#14242feF;border:1px solid #a4ec71;color:#e9f6e5;border-radius:6px;padding:11px 15px;font-size:11px;opacity:0;pointer-events:none;transition:.2s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.toast-stack{position:fixed;right:22px;top:85px;z-index:20}.toast-item{background:#1a2c36;border:1px solid #40564c;border-left:3px solid var(--green);padding:12px 15px;border-radius:7px;margin-bottom:8px;box-shadow:0 8px 25px #0004;animation:slide .25s ease}.toast-item b{display:block;font-size:11px}.toast-item small{display:block;color:#9aabb4;margin-top:4px;font-size:9px}@keyframes slide{from{transform:translateX(20px);opacity:0}to{transform:none;opacity:1}}.modal-backdrop{position:fixed;z-index:30;inset:0;background:#071019c9;display:none;align-items:center;justify-content:center;padding:20px}.modal-backdrop.open{display:flex}.modal{position:relative;width:min(460px,100%);background:#182833;border:1px solid #3a4b54;border-radius:12px;padding:25px;box-shadow:0 20px 70px #0009}.modal-close{position:absolute;right:15px;top:12px;color:#b3c0c6;background:none;border:0;font-size:24px;cursor:pointer}.modal h2{margin:5px 0 8px;font-size:20px}.modal p{color:#9aabb4;font-size:11px;line-height:1.65}.modal .eyebrow{color:var(--green)}.modal-action{width:100%;margin-top:13px;border:0;background:var(--green);color:#18251d;border-radius:6px;padding:12px;font:700 10px var(--mono);cursor:pointer}.modal-action:disabled{background:#45534c;color:#89968e;cursor:not-allowed}.shop-item{display:flex;align-items:center;gap:12px;border-top:1px solid var(--line);padding:13px 0}.shop-item>span{font-size:23px;width:30px}.shop-item div{flex:1}.shop-item b{font-size:11px}.shop-item small{display:block;color:#95a6af;font-size:9px;margin-top:3px}.shop-item button{border:1px solid #52655a;background:#283d34;color:var(--green);border-radius:5px;padding:8px;font:9px var(--mono);cursor:pointer}.shop-item button:disabled{color:#75847b;background:#25312f}.mobile-nav{display:none}
@media(max-width:1050px){.main-layout{grid-template-columns:minmax(0,1fr) 310px;padding:14px;gap:12px}.topbar{padding:0 16px;gap:20px}.bottom-grid{grid-template-columns:1fr}.scene-wrap{height:420px}.objective-panel{display:none}}
@media(max-width:760px){body{font-size:12px}.topbar{height:58px;padding:0 12px;gap:10px}.brand{min-width:unset}.brand-mark{width:31px;height:31px;font-size:20px}.brand b{font-size:13px}.brand small{font-size:6px}.airport-name{display:none}.top-stats{margin-left:auto;gap:13px}.top-stats>div:nth-child(2){display:none}.top-stats small{font-size:7px}.top-stats b{font-size:11px}.top-stats .clock{padding-left:12px}.clock b{font-size:13px}.sound-btn{display:none}.main-layout{display:flex;flex-direction:column;padding:9px 9px 77px;gap:9px}.scene-wrap{height: min(58vh,430px);min-height:300px;border-radius:9px}.scene-bottom{left:8px;right:8px;bottom:8px;gap:5px;flex-wrap:wrap}.camera-switch button{padding:8px 9px;font-size:8px}.scene-hint{font-size:8px;padding:8px}.weather-chip{display:none}.scene-topline{top:8px;left:8px;right:8px}.bottom-grid{display:block;margin-top:9px}.active-flight-panel{padding:13px}.panel h2{font-size:13px}.task-chip{font-size:7px;padding:6px 2px}.task-chip:nth-child(n+5){display:none}.sidebar{display:grid;grid-template-columns:1fr;gap:9px}.sidebar .panel{padding:13px}.crew-panel,.fleet-panel{display:none}.sidebar-footer{display:none}.flight-card{padding:9px 6px}.flight-list{display:grid;grid-template-columns:1fr}.progress-row{margin-top:12px}.flight-main{margin-top:13px}.flight-route b{font-size:9px}.turnaround strong{font-size:13px}.mobile-nav{position:fixed;bottom:0;left:0;right:0;height:62px;background:#111f2a;border-top:1px solid #30424b;display:flex;justify-content:space-around;z-index:10;padding-bottom:env(safe-area-inset-bottom)}.mobile-nav button{flex:1;border:0;background:none;color:#84969f;font-size:17px;display:grid;place-content:center;gap:2px;cursor:pointer}.mobile-nav button small{font:7px var(--mono)}.mobile-nav button.selected{color:var(--green)}.toast-stack{top:65px;right:8px;left:8px}.toast-item{margin-left:auto;width:max-content;max-width:100%}.work-controls{inset:auto 8px 55px 8px}.work-controls>div{grid-template-columns:repeat(3,38px)}.work-controls button{width:38px;height:38px}.work-controls .action-touch{width:auto;padding:0 10px}.scene-wrap.work-mode{height:min(68vh,520px)}.scene-wrap.work-mode .scene-bottom{bottom:8px}.flight-count{font-size:8px}}
@media(min-width:761px) and (max-height:850px){.scene-wrap{height:390px}.main-layout{padding-top:12px}.bottom-grid{margin-top:10px}.panel{padding:14px}}

(() => {
'use strict';
const canvas=document.getElementById('scene'),ctx=canvas.getContext('2d');
const $=id=>document.getElementById(id);
const taskDefs=[['Recibir aeronave','PARE','Posiciónate en la marca y confirma la llegada del avión.'],['Colocar calzos','CALZOS','Asegura las ruedas principales con los calzos.'],['Posicionar equipos','EQUIPO','Acerca la banda transportadora a la bodega.'],['Abrir bodega','BODEGA','Abre la compuerta del compartimento de equipaje.'],['Descargar maletas','DESCARGA','Mueve el equipaje a la cinta transportadora.'],['Clasificar equipaje','CLASIFICAR','Separa las maletas según el destino.'],['Cargar equipaje','CARGA','Carga las maletas de salida en la bodega.'],['Inspección de seguridad','INSPECCIÓN','Revisa el área de plataforma antes del cierre.'],['Retirar equipos','RETIRAR','Desconecta la banda y retira el equipo.'],['Retirar calzos','SALIDA','Confirma plataforma despejada y libera el vuelo.']];
const flights=[{id:'IB 4821',air:'IB',route:'MADRID → BARCELONA',plane:'Airbus A320 · EC-MXY · 174 pax',time:'08:30',state:'EN RODAJE',progress:0,color:'#c93545',dest:'Barcelona'},{id:'VY 2160',air:'VY',route:'PALMA → BARCELONA',plane:'Airbus A319 · EC-MAV · 142 pax',time:'09:15',state:'PROGRAMADO',progress:0,color:'#343f9b',dest:'Palma'},{id:'FR 6382',air:'FR',route:'SEVILLA → BARCELONA',plane:'Boeing 737-800 · EI-DYX · 189 pax',time:'10:05',state:'PROGRAMADO',progress:0,color:'#d5a430',dest:'Sevilla'}];
const state={cash:1250,rep:62,xp:35,level:1,flight:0,mode:'management',task:0,player:{x:310,y:420,walk:0,dir:1},minigame:null,doneFlights:0,crew:[{name:'Tú · Agente de rampa',role:'Líder de operación',icon:'🦺',status:'EN TURNO'}],equip:{tractors:1,carts:2,belt:1},zoom:1,weather:0,sound:true,minutes:42,hour:8, day:1, aircraftMoving:0,toastTimer:null, workStarted:false};
let W=1000,H=600,dpr=1,last=0,ambience=null;
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=Math.max(1,r.width);H=Math.max(1,r.height);canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}window.addEventListener('resize',resize);resize();
function notify(title,sub=''){const stack=$('toastStack'),el=document.createElement('div');el.className='toast-item';el.innerHTML=`<b>${title}</b>${sub?`<small>${sub}</small>`:''}`;stack.append(el);setTimeout(()=>el.remove(),3600)}
function hint(text){const t=$('toast');t.textContent=text;t.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
function money(n){return '€ '+n.toLocaleString('es-ES')}
function renderUI(){ $('cash').textContent=money(state.cash);$('rep').textContent=state.rep;$('time').textContent=`${String(state.hour).padStart(2,'0')}:${String(state.minutes).padStart(2,'0')}`;$('levelText').textContent=`NIVEL ${state.level}`;$('xpFill').style.width=`${state.xp}%`;const f=flights[state.flight];$('flightTitle').innerHTML=`Vuelo ${f.id} <span class="status-pill">${f.state}</span>`;$('airlineBadge').textContent=f.air;$('airlineBadge').style.color=f.color;$('route').innerHTML=f.route.replace(' → ',' <span>→</span> ');$('aircraft').textContent=f.plane;$('turnTime').textContent=`${String(12-Math.floor(state.task*0.6)).padStart(2,'0')}:${String((40-state.task*4+60)%60).padStart(2,'0')}`;$('flightProgress').style.width=`${f.progress*10}%`;$('progressText').textContent=`${f.progress} / 10 tareas`;$('reward').innerHTML=`€ ${420+Math.max(0,state.crew.length-1)*80} <span>+ reputación</span>`;
const chips=taskDefs.map((t,i)=>`<span class="task-chip ${i<f.progress?'done':i===f.progress?'current':''}">${i<f.progress?'✓ ':''}${t[0]}</span>`).join('');$('taskStrip').innerHTML=chips; $('flightCount').textContent=String(flights.length).padStart(2,'0');
$('flightList').innerHTML=flights.map((v,i)=>`<div class="flight-card ${i===state.flight?'selected':''}" data-flight="${i}"><span class="flight-time">${v.time}</span><span class="flight-mini-logo" style="color:${v.color}">${v.air}</span><span class="flight-info"><b>${v.route}</b><small>${v.plane.split(' · ')[0]}</small></span><span class="flight-status ${v.progress===10?'done':''}">${v.progress===10?'COMPLETADO':v.state}</span></div>`).join('');
$('crewList').innerHTML=state.crew.map((p,i)=>`<div class="crew-row"><span class="avatar">${p.icon}</span><span class="crew-data"><b>${p.name}</b><small>${p.role}</small></span><span class="crew-state ${i===0&&state.mode==='work'?'busy':''}">${i===0&&state.mode==='work'?'ACTIVO':p.status}</span></div>`).join('');$('crewAvatars').innerHTML=state.crew.map(p=>`<span>${p.icon}</span>`).join('');$('crewSummary').textContent=`${state.crew.length} ${state.crew.length===1?'agente':'agentes'} · ${Math.max(0,state.crew.length-(state.mode==='work'?1:0))} disponible${state.crew.length===2?'':'s'}`;
$('equipmentList').innerHTML=[['▰','Tractor de equipaje',state.equip.tractors],['▤','Carritos portaequipaje',state.equip.carts],['▱','Cinta transportadora',state.equip.belt]].map(x=>`<div class="equipment-row"><span class="equipment-icon">${x[0]}</span><span><b>${x[1]}</b><small>En servicio</small></span><span class="equipment-count ${x[2]<1?'low':''}">× ${x[2]}</span></div>`).join('');$('contractStatus').textContent=`${Math.max(0,3-state.doneFlights)} escalas restantes hoy`;
$('modeLabel').textContent=state.mode==='work'?'VISTA DE TRABAJO · AGENTE 01':'OPERACIONES EN VIVO';$('sceneHint').innerHTML=state.mode==='work'? (state.minigame?'Pulsa <b>E</b> cuando el indicador esté en la zona verde':`WASD / flechas para moverte · E para interactuar`):'Selecciona un vuelo para coordinar la operación <span>↗</span>';$('workControls').classList.toggle('visible',state.mode==='work');$('scene-wrap')?.classList.toggle('work-mode',state.mode==='work');$('managementBtn').classList.toggle('active',state.mode==='management');$('workBtn').classList.toggle('active',state.mode==='work');$('flightCount').textContent=String(flights.length).padStart(2,'0');}
function startWork(){if(flights[state.flight].progress>=10){hint('Esta escala ya está completada');return}state.mode='work';state.workStarted=true;state.player.x=310;state.player.y=H*.72;state.minigame=null;renderUI();hint('¡A plataforma! Acércate a la marca de trabajo.');}
function setMode(m){if(m==='work')startWork();else{state.mode='management';state.minigame=null;renderUI()}}
function chooseFlight(i){state.flight=i;state.task=flights[i].progress;state.minigame=null;state.player.x=310;renderUI();if(state.mode==='work')hint(`Operación ${flights[i].id} seleccionada`)}
