function frame(now){const dt=Math.min(.05,(now-last)/1000||0);last=now;update(dt);ctx.clearRect(0,0,W,H);ctx.save();if(state.mode==='management'){ctx.translate(W/2,H/2);ctx.scale(state.zoom,state.zoom);ctx.translate(-W/2,-H/2);ctx.scale(W/1000,H/600);drawManagement(now/1000)}else drawWork(now/1000);ctx.restore();requestAnimationFrame(frame)}
function openModal(html){$('modalContent').innerHTML=html;$('modalBackdrop').classList.add('open')}
function closeModal(){$('modalBackdrop').classList.remove('open')}
function shop(){const items=[['🚜','Tractor de equipaje','Duplica tu capacidad de remolque · +€ 160 por escala',650,'tractors'],['▤','Carritos portaequipaje','Más equipaje en cada operación · +€ 70 por escala',280,'carts'],['▱','Cinta transportadora','Descarga más rápida y segura · +€ 110 por escala',480,'belt']];openModal(`<span class="eyebrow">MERCADO DE EQUIPOS</span><h2>Mejora tu operación</h2><p>Invierte en equipo de plataforma para atender vuelos más grandes y cobrar contratos de mayor valor.</p>${items.map(it=>`<div class="shop-item"><span>${it[0]}</span><div><b>${it[1]}</b><small>${it[2]}</small></div><button data-buy="${it[4]}" data-cost="${it[3]}">${money(it[3])}</button></div>`).join('')}<button class="modal-action" id="modalDone">VOLVER A LA OPERACIÓN</button>`)}
function crewModal(){const price=350+Math.max(0,state.crew.length-1)*150;openModal(`<span class="eyebrow">GESTIÓN DE PERSONAL</span><h2>Amplía tu cuadrilla</h2><p>Los agentes contratados trabajan en operaciones de apoyo y aumentan el valor de cada escala. El primer agente que contrates se asignará automáticamente a las tareas rutinarias.</p><div class="shop-item"><span>🦺</span><div><b>Agente de rampa</b><small>Salario por turno € 45 · Capacidad de equipo +1</small></div><button data-hire="true" ${state.cash<price?'disabled':''}>${money(price)}</button></div><div style="font-size:10px;color:#91a5a9;margin-top:8px">CUADRILLA ACTUAL · ${state.crew.length} ${state.crew.length===1?'AGENTE':'AGENTES'}</div><button class="modal-action" id="modalDone">LISTO</button>`)}
function hire(){const price=350+Math.max(0,state.crew.length-1)*150;if(state.cash<price){notify('Fondos insuficientes','Completa más tareas para contratar.');return}state.cash-=price;const names=['Nora','Dani','Alex','Sam','Iris','Leo'];state.crew.push({name:`${names[(state.crew.length-1)%names.length]} · Agente`,role:'Operaciones de equipaje',icon:['🦺','👷','🦺','👷'][state.crew.length%4],status:'DISPONIBLE'});state.rep=Math.min(100,state.rep+1);notify('Agente contratado',`Cuadrilla ampliada · ${state.crew.length} agentes disponibles`);renderUI();crewModal()}
function buy(id,cost){if(state.cash<cost){notify('Fondos insuficientes','Completa tareas para aumentar la caja.');return}state.cash-=cost;state.equip[id]++;notify('Equipo adquirido','Disponible en la plataforma de inmediato.');renderUI();shop()}
function schedule(){if(flights.length>=6){notify('Plan de vuelos completo','No hay posiciones libres para más vuelos.');return}const options=[['U2','MÁLAGA → BARCELONA','Airbus A320neo · OE-IZT · 186 pax','#e69b35'],['IB','VALENCIA → BARCELONA','Airbus A321 · EC-ILP · 210 pax','#c93545'],['VY','BILBAO → BARCELONA','Airbus A320 · EC-LZM · 180 pax','#343f9b']];const v=options[(flights.length-3)%options.length];const hour=9+flights.length-2;const f={id:`${v[0]} ${Math.floor(1000+Math.random()*8000)}`,air:v[0],route:v[1],plane:v[2],time:`${String(hour).padStart(2,'0')}:30`,state:'PROGRAMADO',progress:0,color:v[3],dest:v[1].split(' → ')[0]};flights.push(f);notify('Vuelo programado',`${f.id} · ${f.time} · nueva operación contratada`);renderUI();closeModal()}
function flightDetails(){const f=flights[state.flight];openModal(`<span class="eyebrow">FICHA DE VUELO · ${f.id}</span><h2>${f.route}</h2><p>${f.plane}<br>Puerta asignada: Plataforma Norte · Posición ${String(state.flight+1).padStart(2,'0')}<br>Hora estimada: ${f.time} · Tiempo objetivo de escala: 45 min</p><div style="background:#20323a;border-radius:6px;padding:12px;color:#afc0c5;font-size:10px;line-height:1.9">SERVICIO CONTRATADO<br>▣ Descarga y clasificación de equipaje<br>▣ Carga de bodega y preparación de salida<br>▣ Seguridad de plataforma y retirada de equipo<br><b style="color:#a4ec71">BONO DE ESCALA PERFECTA: € 420</b></div><button class="modal-action" id="beginFromDetails">COMENZAR OPERACIÓN</button>`)}
$('managementBtn').addEventListener('click',()=>setMode('management'));$('workBtn').addEventListener('click',()=>setMode('work'));$('flightList').addEventListener('click',e=>{const card=e.target.closest('[data-flight]');if(card)chooseFlight(+card.dataset.flight)});$('detailsBtn').addEventListener('click',flightDetails);$('scheduleBtn').addEventListener('click',schedule);$('hireBtn').addEventListener('click',crewModal);$('shopBtn').addEventListener('click',shop);$('allFlightsBtn').addEventListener('click',()=>openModal(`<span class="eyebrow">OPERACIONES PROGRAMADAS</span><h2>Plan de vuelos</h2><p>Turno de mañana · ${flights.length} vuelos asignados a Plataforma Norte.</p>${flights.map((f,i)=>`<div class="shop-item"><span class="flight-mini-logo" style="color:${f.color}">${f.air}</span><div><b>${f.id} · ${f.route}</b><small>${f.time} · ${f.progress}/10 tareas · ${f.state}</small></div><button data-selectflight="${i}">VER</button></div>`).join('')}<button class="modal-action" id="modalDone">CERRAR PLAN</button>`));$('zoomIn').addEventListener('click',()=>state.zoom=Math.min(1.35,state.zoom+.1));$('zoomOut').addEventListener('click',()=>state.zoom=Math.max(.82,state.zoom-.1));$('fullscreen').addEventListener('click',()=>{if(!document.fullscreenElement)document.querySelector('.scene-wrap').requestFullscreen?.();else document.exitFullscreen?.()});$('soundBtn').addEventListener('click',()=>{state.sound=!state.sound;$('soundBtn').textContent=state.sound?'◖))':'◖×';if(state.sound)playTone(480,.08)});
$('modalClose').addEventListener('click',closeModal);$('modalBackdrop').addEventListener('click',e=>{if(e.target===$('modalBackdrop'))closeModal()});$('modalContent').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.buy)buy(b.dataset.buy,+b.dataset.cost);if(b.dataset.hire)hire();if(b.id==='modalDone')closeModal();if(b.id==='beginFromDetails'){closeModal();startWork()}if(b.dataset.selectflight){closeModal();chooseFlight(+b.dataset.selectflight)}});
$('mobileCrew').addEventListener('click',crewModal);$('mobileShop').addEventListener('click',shop);$('mobilePlan').addEventListener('click',()=>$('allFlightsBtn').click());
canvas.addEventListener('pointerdown',e=>{if(state.mode==='management'){const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*1000,y=(e.clientY-r.top)/r.height*600;if(y>260&&y<475){const i=Math.max(0,Math.min(flights.length-1,Math.floor((x-355)/182)));chooseFlight(i)}}});
function updateWeather(){const weather=['☀ DESPEJADO','⛅ NUBES ALTAS','🌦 LLUVIA LIGERA'];state.weather=(state.weather+1)%weather.length;$('weather').textContent=weather[state.weather];$('weatherChip').innerHTML=`${['☀','⛅','🌦'][state.weather]} &nbsp;${[19,17,15][state.weather]}° &nbsp;Viento ${[8,14,21][state.weather]} km/h`;if(state.weather===2)notify('Cambio de tiempo','Lluvia ligera · Operaciones con precaución')}
setInterval(updateWeather,90000);renderUI();requestAnimationFrame(frame);
})();

